insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','ProductCategory','product-category','/business/product-category','商品分类','ri:folder-chart-line',4 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='ProductCategory');
insert into sys_menu(parent_id,type,name,path,component,title,icon,sort_no) select id,'MENU','ServiceItem','service-item','/business/service-item','基础服务','ri:service-line',5 from sys_menu where name='Business' and not exists(select 1 from sys_menu where name='ServiceItem');
insert into sys_menu(parent_id,type,name,title,auth_mark,sort_no) select p.id,'BUTTON',concat(p.name,a.suffix),a.title,a.mark,a.sort_no from sys_menu p join (
insert into sys_role_menu(role_id,menu_id) select r.id,m.id from sys_role r cross join sys_menu m where r.code='admin' and not exists(select 1 from sys_role_menu x where x.role_id=r.id and x.menu_id=m.id);
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select id,null,'delta-category','三角洲行动',1,true from pw_game where game_code='delta-force' and not exists(select 1 from pw_product_category where category_code='delta-category');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select g.id,p.id,'delta-regular','常规套餐',1,true from pw_game g join pw_product_category p on p.category_code='delta-category' where g.game_code='delta-force' and not exists(select 1 from pw_product_category where category_code='delta-regular');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select g.id,p.id,'delta-single','单局套餐',2,true from pw_game g join pw_product_category p on p.category_code='delta-category' where g.game_code='delta-force' and not exists(select 1 from pw_product_category where category_code='delta-single');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select g.id,p.id,'delta-special','专项服务',3,true from pw_game g join pw_product_category p on p.category_code='delta-category' where g.game_code='delta-force' and not exists(select 1 from pw_product_category where category_code='delta-special');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select id,null,'valorant-category','无畏契约',2,true from pw_game where game_code='valorant' and not exists(select 1 from pw_product_category where category_code='valorant-category');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select g.id,p.id,'valorant-ranked','排位上分',1,true from pw_game g join pw_product_category p on p.category_code='valorant-category' where g.game_code='valorant' and not exists(select 1 from pw_product_category where category_code='valorant-ranked');
insert into pw_product_category(game_id,parent_id,category_code,category_name,sort_no,enabled) select g.id,p.id,'valorant-training','教学陪练',2,true from pw_game g join pw_product_category p on p.category_code='valorant-category' where g.game_code='valorant' and not exists(select 1 from pw_product_category where category_code='valorant-training');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'delta-warfare','全面战场陪玩','COMPANION','团队配合、地图轮转与大战场指挥',1,true from pw_game where game_code='delta-force' and not exists(select 1 from pw_service_item where service_code='delta-warfare');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'delta-escort','烽火地带护航','ESCORT','跑图、物资规划和撤离护航',2,true from pw_game where game_code='delta-force' and not exists(select 1 from pw_service_item where service_code='delta-escort');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'delta-map-clear','清图专项','MAP_CLEAR','指定地图专项服务',3,true from pw_game where game_code='delta-force' and not exists(select 1 from pw_service_item where service_code='delta-map-clear');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'valorant-ranked','无畏契约排位','RANKING','双排或组队排位服务',1,true from pw_game where game_code='valorant' and not exists(select 1 from pw_service_item where service_code='valorant-ranked');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'valorant-teaching','无畏契约教学','TEACHING','枪法、道具、站位和复盘教学',2,true from pw_game where game_code='valorant' and not exists(select 1 from pw_service_item where service_code='valorant-teaching');
insert into pw_service_item(game_id,service_code,service_name,service_type,description,sort_no,enabled) select id,'valorant-casual','无畏契约娱乐陪玩','COMPANION','娱乐匹配与轻松组队',3,true from pw_game where game_code='valorant' and not exists(select 1 from pw_service_item where service_code='valorant-casual');
