create table pw_product_category (id bigint generated by default as identity primary key, game_id bigint, parent_id bigint, category_code varchar(64) not null unique, category_name varchar(64) not null, icon_url varchar(512), sort_no integer not null default 0, enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create index ix_pw_product_category_parent on pw_product_category(parent_id);
create index ix_pw_product_category_game on pw_product_category(game_id);
create table pw_service_item (id bigint generated by default as identity primary key, game_id bigint not null, service_code varchar(64) not null unique, service_name varchar(64) not null, service_type varchar(32) not null, description varchar(1000), sort_no integer not null default 0, enabled boolean not null default true, created_at timestamp not null default current_timestamp, updated_at timestamp not null default current_timestamp);
create index ix_pw_service_item_game on pw_service_item(game_id);

 select 'ProductCategory' parent_name,'List' suffix,'查询商品分类' title,'business:product-category:list' mark,1 sort_no union all select 'ProductCategory','Create','新增商品分类','business:product-category:create',2 union all select 'ProductCategory','Update','编辑商品分类','business:product-category:update',3 union all select 'ProductCategory','Status','修改分类状态','business:product-category:status',4 union all select 'ProductCategory','Delete','删除商品分类','business:product-category:delete',5 union all
